// Builds the devtools inspector (src/devtools/ui/) into src/devtools/ui-assets.generated.ts:
// a minified app.js (Preact bundled in), a minified app.css and index.html, embedded as
// strings that src/devtools/server.ts serves under the devtools path (ADR 0011).
//
//   node scripts/build-devtools-ui.mjs           write the generated file
//   node scripts/build-devtools-ui.mjs --check   fail if the committed file is stale
//
// The output is deterministic: the same sources give a byte-identical file.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gzipSync } from 'node:zlib';
import { build } from 'esbuild';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const uiDir = resolve(root, 'src/devtools/ui');
const outFile = resolve(root, 'src/devtools/ui-assets.generated.ts');
const check = process.argv.includes('--check');

/** @type {import('esbuild').BuildOptions} */
const common = {
  absWorkingDir: root,
  bundle: true,
  minify: true,
  write: false,
  outdir: 'out',
  platform: 'browser',
  // Browsers with <dialog>, :focus-visible, Object.hasOwn and CSS rgb() space syntax.
  target: ['es2022', 'chrome111', 'edge111', 'firefox111', 'safari16.4'],
  charset: 'ascii',
  legalComments: 'none',
  sourcemap: false,
  logLevel: 'warning',
};

async function bundle(entry, options = {}) {
  const result = await build({ ...common, ...options, entryPoints: [resolve(uiDir, entry)] });
  const [file] = result.outputFiles ?? [];
  if (file === undefined) throw new Error(`esbuild produced no output for ${entry}`);
  return file.text;
}

const js = await bundle('main.ts', {
  format: 'esm',
  define: { 'process.env.NODE_ENV': '"production"' },
  banner: {
    js: '/* Shoehive devtools inspector. Includes Preact, MIT License, Copyright (c) 2015-present Jason Miller. */',
  },
});
const css = await bundle('app.css');

const html = [
  '<!doctype html>',
  '<html lang="en">',
  '<head>',
  '<meta charset="utf-8">',
  '<meta name="viewport" content="width=device-width, initial-scale=1">',
  '<meta name="color-scheme" content="light dark">',
  '<meta name="referrer" content="no-referrer">',
  '<title>Shoehive devtools</title>',
  '<link rel="stylesheet" href="app.css">',
  '<script type="module" src="app.js"></script>',
  '</head>',
  '<body>',
  '<div id="app"><noscript>The Shoehive inspector needs JavaScript.</noscript></div>',
  '</body>',
  '</html>',
  '',
].join('\n');

const assets = [
  ['index.html', 'text/html; charset=utf-8', html],
  ['app.js', 'text/javascript; charset=utf-8', js],
  ['app.css', 'text/css; charset=utf-8', css],
];

for (const [name, , body] of assets) {
  if (/[^\t\n\r -~]/.test(body)) {
    throw new Error(`${name} contains non-ASCII characters; keep the bundle ASCII-only`);
  }
}

const entries = assets
  .map(
    ([name, type, body]) =>
      `  ${JSON.stringify(name)}: {\n    type: ${JSON.stringify(type)},\n    body: ${JSON.stringify(body)},\n  },\n`,
  )
  .join('');

const source =
  '// Generated by scripts/build-devtools-ui.mjs from src/devtools/ui/. Do not edit.\n' +
  '// Rebuild with `pnpm --filter shoehive devtools:ui`; `devtools:ui:check` verifies it.\n' +
  '\n' +
  "/** The inspector's static files, served under the devtools path (ADR 0011). */\n" +
  'export const DEVTOOLS_UI: Readonly<Record<string, { type: string; body: string }>> = {\n' +
  entries +
  '};\n';

const sizes = assets
  .map(
    ([name, , body]) =>
      `${name} ${(Buffer.byteLength(body) / 1024).toFixed(1)} kB (${(gzipSync(body, { level: 9 }).length / 1024).toFixed(1)} kB gzip)`,
  )
  .join(', ');
const shown = relative(process.cwd(), outFile) || outFile;

if (check) {
  let current = '';
  try {
    current = readFileSync(outFile, 'utf8');
  } catch {
    // Missing counts as stale.
  }
  if (current !== source) {
    console.error(
      `${shown} is out of date with src/devtools/ui/. Run \`pnpm --filter shoehive devtools:ui\` and commit the result.`,
    );
    process.exit(1);
  }
  console.log(`${shown} is up to date: ${sizes}`);
} else {
  writeFileSync(outFile, source);
  console.log(`Wrote ${shown}: ${sizes}`);
}
